import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { spawnSync } from 'node:child_process';
try {
  const event = JSON.parse(readFileSync(0, 'utf8'));
  const root = resolve(event.cwd);
  const file = resolve(root, event.tool_input?.file_path ?? '');
  const allowed = ['app.js', 'model.js'].map(name => resolve(root, name));
  if (allowed.includes(file)) {
    const result = spawnSync(process.execPath, ['--check', file], { encoding: 'utf8' });
    if (result.error) throw result.error;
    if (result.status !== 0) {
      console.log(JSON.stringify({
        systemMessage: 'JavaScript 語法檢查失敗，請查看該檔案。',
        hookSpecificOutput: {
          hookEventName: 'PostToolUse',
          additionalContext: '請修正語法錯誤並重新檢查：' + result.stderr.slice(0, 3000)
        }
      }));
    }
  }
} catch (error) {
  console.error(String(error));
  process.exitCode = 1;
}

